import * as React from "react";

export type ClipboardIconProps = React.SVGProps<SVGSVGElement> & { size?: number };

export function ClipboardIcon({ size = 20, ...props }: ClipboardIconProps) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.8"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      {...props}
    >
      <rect x="6" y="5" width="12" height="15.5" rx="1" /><rect x="9" y="3" width="6" height="3.5" rx="0.8" /><path d="M9 11.5 L15 11.5 M9 14.5 L15 14.5" />
    </svg>
  );
}
